Código
group.sizes =
  temperatura |&gt;
  pull(estado) |&gt;
  table()

n = sum(group.sizes)
n.fac = 3

group.limits =
  group.sizes |&gt;
  {\(x) list(
    c(1, (cumsum(x) + 1)[1:(length(x)-1)])[1:length(x)],
    cumsum(x)
  )}()

contr = matrix(0, nrow = n, ncol = n.fac)
for (i in 1:n.fac) {
  contr[group.limits[[1]][i] : group.limits[[2]][i], i] = rep(1, group.sizes[i])
}

contr[contr!=0] = 1:sum(contr!=0)

X =
  temperatura |&gt;
  select(starts_with("X"))

data = list(
  X = X,
  n_row = nrow(X),
  n_col = ncol(X),
  n_fac = 3,
  n_alpha_free = max(contr),
  sigma_shape = .1,
  sigma_rate  = .1,
  alpha_status = contr
)

init = list()
n_chains = 2
for (i in 1:n_chains) {
  init[[i]] = list(
    alpha_ = rep(10, data$n_alpha_free),
    lambda = matrix(0, data$n_fac, data$n_col),
    sigma  = matrix(1, data$n_row, 1)
  )
}



fit_FA = sampling(mod_FA, data = data, chains = n_chains, init = init, seed = 12345)



